/*
 * U8G2 OLED Display Example
 *
 * Demonstrates text, shapes, and animations on 128x64 SSD1306 OLED.
 *
 * Wiring:
 *   OLED VCC -> Arduino 5V
 *   OLED GND -> Arduino GND
 *   OLED SCL -> Arduino A5 (SCL)
 *   OLED SDA -> Arduino A4 (SDA)
 *
 * I2C Address: 0x3C (default for SSD1306)
 */

#include <U8g2lib.h>
#include <Wire.h>

// Initialize U8G2 for SSD1306 128x64 OLED (I2C)
U8G2_SSD1306_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0);

// Animation variables
int counter = 0;
int ballX = 64;
int ballY = 32;
int ballDX = 2;
int ballDY = 1;

void setup() {
  Serial.begin(115200);
  Serial.println("U8G2 OLED Demo");

  // Initialize OLED
  u8g2.begin();

  Serial.println("OLED initialized!");
}

void loop() {
  // Demo 1: Welcome screen with title
  drawWelcomeScreen();
  delay(3000);

  // Demo 2: Text formatting showcase
  drawTextShowcase();
  delay(3000);

  // Demo 3: Shapes demo
  drawShapesDemo();
  delay(3000);

  // Demo 4: Animation with bouncing ball
  for (int i = 0; i < 200; i++) {
    drawBouncingBall();
    delay(20);
  }

  // Demo 5: Counter display
  drawCounter();
  delay(3000);
}

// Welcome screen with centered title
void drawWelcomeScreen() {
  u8g2.clearBuffer();

  // Draw border frame
  u8g2.drawFrame(0, 0, 128, 64);

  // Title
  u8g2.setFont(u8g2_font_ncenB14_tr);
  u8g2.drawStr(20, 25, "U8G2");

  // Subtitle
  u8g2.setFont(u8g2_font_ncenB08_tr);
  u8g2.drawStr(15, 45, "OLED Display");

  // Version
  u8g2.setFont(u8g2_font_5x7_tr);
  u8g2.drawStr(35, 58, "v1.0 Demo");

  u8g2.sendBuffer();
}

// Text formatting showcase
void drawTextShowcase() {
  u8g2.clearBuffer();

  // Title
  u8g2.setFont(u8g2_font_ncenB08_tr);
  u8g2.drawStr(10, 12, "Font Gallery");
  u8g2.drawHLine(10, 15, 108);

  // Different font sizes
  u8g2.setFont(u8g2_font_5x7_tr);
  u8g2.drawStr(10, 25, "5x7: Small text");

  u8g2.setFont(u8g2_font_6x10_tr);
  u8g2.drawStr(10, 37, "6x10: Medium");

  u8g2.setFont(u8g2_font_7x14_tr);
  u8g2.drawStr(10, 53, "7x14: Large");

  u8g2.sendBuffer();
}

// Shapes demonstration
void drawShapesDemo() {
  u8g2.clearBuffer();

  // Title
  u8g2.setFont(u8g2_font_5x7_tr);
  u8g2.drawStr(10, 10, "Shapes Demo");

  // Rectangle (frame)
  u8g2.drawFrame(10, 18, 30, 20);

  // Filled rectangle
  u8g2.drawBox(50, 18, 30, 20);

  // Circle (outline)
  u8g2.drawCircle(110, 28, 12, U8G2_DRAW_ALL);

  // Triangle
  u8g2.drawTriangle(20, 55, 40, 45, 60, 55);

  // Cross pattern
  u8g2.drawHLine(70, 45, 50);
  u8g2.drawVLine(95, 40, 20);

  u8g2.sendBuffer();
}

// Bouncing ball animation
void drawBouncingBall() {
  u8g2.clearBuffer();

  // Draw border
  u8g2.drawFrame(0, 0, 128, 64);

  // Update ball position
  ballX += ballDX;
  ballY += ballDY;

  // Bounce off walls
  if (ballX >= 124 || ballX <= 3) ballDX = -ballDX;
  if (ballY >= 60 || ballY <= 3) ballDY = -ballDY;

  // Draw ball (filled circle)
  u8g2.drawDisc(ballX, ballY, 4, U8G2_DRAW_ALL);

  // Draw score
  u8g2.setFont(u8g2_font_5x7_tr);
  u8g2.drawStr(5, 12, "Bouncing Ball");

  // Draw position info
  char buf[20];
  sprintf(buf, "X:%d Y:%d", ballX, ballY);
  u8g2.drawStr(5, 58, buf);

  u8g2.sendBuffer();
}

// Counter display
void drawCounter() {
  u8g2.clearBuffer();

  // Title
  u8g2.setFont(u8g2_font_ncenB08_tr);
  u8g2.drawStr(20, 15, "Counter");

  // Large counter number
  u8g2.setFont(u8g2_font_10x20_tr);
  char numStr[10];
  sprintf(numStr, "%d", counter);
  u8g2.drawStr(35, 45, numStr);

  // Increment counter
  counter++;
  if (counter > 999) counter = 0;

  u8g2.sendBuffer();
}
